            rule['properties']['tags'] = ['license', 'security', '']
            self.assertEqual(c.classify(fs, config, sarif)['finding_counts_by_kind_and_severity']['Licenses/UNRANKED'], 1)
            sarif['runs'][0]['results'].remove(license_result)
