        fs, config, sarif = self.actual()
        uri = sarif['runs'][0]['originalUriBaseIds']['ROOTPATH']['uri']
        source = Path(uri.removeprefix('file://').removesuffix('/'))
        c.classify(fs, config, sarif, source)
